\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Samsung Color Theme (Deep Navy + Blue Accent + Gold Premium) ──
\definecolor{primary}{HTML}{0A1628}
\definecolor{secondary}{HTML}{1428A0}
\definecolor{accent}{HTML}{2196F3}
\definecolor{gold}{HTML}{C89B3C}
\definecolor{bgposter}{HTML}{0D1B2A}
\definecolor{cardbg}{HTML}{111D30}
\definecolor{cardlight}{HTML}{162240}
\definecolor{cardblue}{HTML}{0F1F3D}
\definecolor{cardgold}{HTML}{1A1E2E}
\definecolor{statbg}{HTML}{0F1A2E}
\definecolor{textwhite}{HTML}{FFFFFF}
\definecolor{textsilver}{HTML}{B0BEC5}
\definecolor{textgray}{HTML}{78909C}
\definecolor{accentglow}{HTML}{1565C0}
\definecolor{goldglow}{HTML}{FFD54F}
\definecolor{herobg}{HTML}{0C1830}
\definecolor{tablebg}{HTML}{0E1A2F}
\definecolor{tablerow}{HTML}{13213A}
\definecolor{tablehead}{HTML}{1428A0}

\pagecolor{bgposter}
\color{textwhite}

\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=4pt,
  label={\color{gold}\bfseries\arabic*.}}

% ── Card Styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardblue,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25},
  },
  goldcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardgold,
    borderline west={4pt}{0pt}{gold},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{gold},
    coltitle=gold, colbacktitle=cardgold,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={gold!40},
    valign=top, drop shadow={opacity=0.25},
  },
  herocard/.style={
    enhanced, arc=6pt, boxrule=1pt, colframe=gold!60,
    colback=herobg,
    borderline west={5pt}{0pt}{gold},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{gold},
    coltitle=gold, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={gold!50},
    valign=top, drop shadow={opacity=0.3},
  },
  aicard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=secondary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=secondary!25!primary,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=secondary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════
% TITLE BAR — Samsung Galaxy Ecosystem 2025
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=16pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4},
  borderline south={4pt}{0pt}{secondary},
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{36}{42}\selectfont\color{textsilver}\textbf{SAMSUNG}}\\[10pt]
  {\fontsize{86}{102}\selectfont\bfseries Galaxy Ecosystem 2025}\\[14pt]
  {\fontsize{38}{46}\selectfont\color{textsilver} Innovation Across Every Category}\\[10pt]
  {\fontsize{30}{36}\selectfont\color{accent} Smartphones\;\textbar\;Foldables\;\textbar\;Tablets\;\textbar\;Wearables\;\textbar\;Audio\;\textbar\;TV \& Home\;\textbar\;Smart Appliances}
}

% ══════════════════════════════════════════════════════════
% STAT BANNER — Key Numbers
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={3pt}{0pt}{accent!30},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{gold!50}{primary!80!black}{\parbox{0.86\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{gold} 7+}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Product Categories}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{accent!50}{primary!80!black}{\parbox{0.86\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{accent} 14}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Featured Products}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{gold!50}{primary!80!black}{\parbox{0.86\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{gold} 2}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} New Flagships}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{accent!50}{primary!80!black}{\parbox{0.86\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{accent} 4+}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} AI-Branded Products}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════
% HERO ZONE — Galaxy S26 Ultra (Left, spanning cols 1-2)
% ══════════════════════════════════════════════════════════
\posterbox[herocard, title={\raisebox{0pt}{\colorbox{gold!20!primary}{\;\textsc{NEW}\;}}~Galaxy S26 Ultra}
]{name=heros26, column=1, span=2, between=row5 and row10}{
  \fontsize{34}{44}\selectfont\color{textsilver}
  \vspace{4pt}

  \colorbox{primary!70}{\parbox{0.95\linewidth}{\centering\vspace{6pt}
    {\fontsize{44}{52}\selectfont\bfseries\color{gold} Samsung's Most Advanced Smartphone}\\[6pt]
    {\fontsize{30}{38}\selectfont\color{textsilver} The pinnacle of the Ultra series for 2025}
  \vspace{6pt}}}

  \vspace{14pt}

  \begin{minipage}[t]{0.48\linewidth}
    \begin{itemize}[itemsep=10pt, label={\color{gold}$\blacktriangleright$}]
      \item {\bfseries\color{textwhite}Pro-Grade Camera System}\\
        {\fontsize{30}{38}\selectfont Next-gen computational photography}
      \item {\bfseries\color{textwhite}Integrated S~Pen}\\
        {\fontsize{30}{38}\selectfont Precision stylus, built in}
      \item {\bfseries\color{textwhite}Premium Materials}\\
        {\fontsize{30}{38}\selectfont Titanium frame, flagship build}
    \end{itemize}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \begin{itemize}[itemsep=10pt, label={\color{gold}$\blacktriangleright$}]
      \item {\bfseries\color{textwhite}Galaxy AI On-Device}\\
        {\fontsize{30}{38}\selectfont Real-time translation \& photo AI}
      \item {\bfseries\color{textwhite}Flagship Performance}\\
        {\fontsize{30}{38}\selectfont Top-tier processor for 2025}
      \item {\bfseries\color{textwhite}All-Day Battery}\\
        {\fontsize{30}{38}\selectfont Power for every task}
    \end{itemize}
  \end{minipage}

  \vspace{10pt}
  \begin{center}
    \colorbox{gold!25!primary}{\parbox{0.6\linewidth}{\centering\vspace{6pt}
      {\fontsize{36}{44}\selectfont\bfseries\color{gold} $\star$ FLAGSHIP LAUNCH 2025 $\star$}
    \vspace{6pt}}}
  \end{center}
}

% ══════════════════════════════════════════════════════════
% HERO ZONE — Galaxy Buds4 Pro (Right column)
% ══════════════════════════════════════════════════════════
\posterbox[herocard, title={\raisebox{0pt}{\colorbox{gold!20!primary}{\;\textsc{NEW}\;}}~Galaxy Buds4 Pro}
]{name=herobuds, column=3, span=1, between=row5 and row10}{
  \fontsize{34}{44}\selectfont\color{textsilver}
  \vspace{4pt}

  \colorbox{primary!70}{\parbox{0.94\linewidth}{\centering\vspace{6pt}
    {\fontsize{38}{46}\selectfont\bfseries\color{gold} Next-Gen Audio}\\[4pt]
    {\fontsize{28}{34}\selectfont\color{textsilver} Premium ANC \& Hi-Fi Sound}
  \vspace{6pt}}}

  \vspace{14pt}

  \begin{itemize}[itemsep=10pt, label={\color{gold}$\blacktriangleright$}]
    \item {\bfseries\color{textwhite}Advanced ANC}\\
      {\fontsize{30}{38}\selectfont Next-generation active noise cancellation}
    \item {\bfseries\color{textwhite}Hi-Fi Audio}\\
      {\fontsize{30}{38}\selectfont Studio-quality sound reproduction}
    \item {\bfseries\color{textwhite}Seamless Pairing}\\
      {\fontsize{30}{38}\selectfont Instant connect across all Galaxy devices}
    \item {\bfseries\color{textwhite}Galaxy AI Audio}\\
      {\fontsize{30}{38}\selectfont Intelligent sound adaptation}
  \end{itemize}

  \vspace{8pt}
  \begin{center}
    \colorbox{gold!25!primary}{\parbox{0.86\linewidth}{\centering\vspace{6pt}
      {\fontsize{32}{40}\selectfont\bfseries\color{gold} $\star$ FLAGSHIP LAUNCH $\star$}
    \vspace{6pt}}}
  \end{center}
}

% ══════════════════════════════════════════════════════════
% ECOSYSTEM — Full Product Portfolio
% ══════════════════════════════════════════════════════════
\posterbox[aicard, title={The Complete Galaxy Ecosystem}
]{name=ecosystem, column=1, span=2, between=row10 and row14}{
  \fontsize{32}{42}\selectfont\color{textsilver}
  \vspace{2pt}

  \begin{minipage}[t]{0.32\linewidth}
    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Smartphones}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Galaxy S26 Ultra}\\
      {\fontsize{24}{30}\selectfont\color{gold} \textsc{new}}
    \vspace{6pt}}}

    \vspace{10pt}

    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Foldables}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Galaxy Z Fold7}\\
      {\fontsize{28}{34}\selectfont\color{textsilver} Galaxy Z Flip7}
    \vspace{6pt}}}

    \vspace{10pt}

    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Tablets}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Galaxy Tab S11 Series}
    \vspace{6pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.32\linewidth}
    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Wearables}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Galaxy Watch Ultra}
    \vspace{6pt}}}

    \vspace{10pt}

    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Audio}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Galaxy Buds4 Pro}\\
      {\fontsize{24}{30}\selectfont\color{gold} \textsc{new}}\\[2pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Q-series Soundbar}
    \vspace{6pt}}}

    \vspace{10pt}

    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Television}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Neo QLED 8K TV}\\
      {\fontsize{28}{34}\selectfont\color{textsilver} The Frame Pro}
    \vspace{6pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.32\linewidth}
    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Monitors}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Odyssey OLED G9}\\
      {\fontsize{28}{34}\selectfont\color{textsilver} Gaming Monitor}
    \vspace{6pt}}}

    \vspace{10pt}

    \colorbox{cardlight}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{36}{44}\selectfont\bfseries\color{accent} Smart Home}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textsilver} Bespoke AI Fridge}\\
      {\fontsize{28}{34}\selectfont\color{textsilver} Bespoke AI Laundry}\\
      {\fontsize{28}{34}\selectfont\color{textsilver} Jet Stick Vacuums}\\
      {\fontsize{28}{34}\selectfont\color{textsilver} Air Conditioners}
    \vspace{6pt}}}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════
% AI INTEGRATION — Right column middle
% ══════════════════════════════════════════════════════════
\posterbox[highlightcard, title={AI-Powered Everything}
]{name=aizone, column=3, span=1, between=row10 and row14}{
  \fontsize{33}{43}\selectfont\color{textsilver}
  \vspace{4pt}

  \colorbox{accent!20!primary}{\parbox{0.94\linewidth}{\vspace{8pt}\centering
    {\fontsize{40}{48}\selectfont\bfseries\color{accent} Galaxy AI}\\[6pt]
    {\fontsize{30}{38}\selectfont\color{textsilver} On-device intelligence across\\smartphones, foldables \& tablets}
  \vspace{8pt}}}

  \vspace{12pt}

  \colorbox{gold!15!primary}{\parbox{0.94\linewidth}{\vspace{8pt}\centering
    {\fontsize{40}{48}\selectfont\bfseries\color{gold} Bespoke AI}\\[6pt]
    {\fontsize{30}{38}\selectfont\color{textsilver} Smarter energy management,\\usage learning \& personalized\\automation for home appliances}
  \vspace{8pt}}}

  \vspace{12pt}

  \begin{itemize}[itemsep=8pt, label={\color{accent}$\blacktriangleright$}]
    \item {\color{textwhite}\bfseries Photo \& video intelligence}
    \item {\color{textwhite}\bfseries Real-time translation}
    \item {\color{textwhite}\bfseries Smart home automation}
    \item {\color{textwhite}\bfseries Adaptive energy savings}
  \end{itemize}
}

% ══════════════════════════════════════════════════════════
% CATEGORY HIGHLIGHTS TABLE — Full width
% ══════════════════════════════════════════════════════════
\posterbox[navycard, title={Category Highlights at a Glance}
]{name=cattable, column=1, span=3, between=row14 and row19}{
  \fontsize{30}{40}\selectfont
  \vspace{4pt}

  \centering
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{@{\hspace{12pt}}p{0.15\linewidth}@{\hspace{12pt}}p{0.32\linewidth}@{\hspace{12pt}}p{0.12\linewidth}@{\hspace{24pt}}p{0.15\linewidth}@{\hspace{12pt}}p{0.32\linewidth}@{\hspace{12pt}}p{0.12\linewidth}@{\hspace{12pt}}}
    \rowcolor{tablehead}
    {\bfseries\color{textwhite} Category} & {\bfseries\color{textwhite} Product} & {\bfseries\color{textwhite} Status} &
    {\bfseries\color{textwhite} Category} & {\bfseries\color{textwhite} Product} & {\bfseries\color{textwhite} Status} \\
    \rowcolor{tablerow}
    {\color{accent}\bfseries Smartphones} & Galaxy S26 Ultra & {\color{gold}\bfseries NEW} &
    {\color{accent}\bfseries Television} & Neo QLED 8K TV & {\color{textsilver} Current} \\
    \rowcolor{tablebg}
    {\color{accent}\bfseries Foldables} & Galaxy Z Fold7 & {\color{textsilver} Current} &
    {\color{accent}\bfseries Television} & The Frame Pro & {\color{textsilver} Current} \\
    \rowcolor{tablerow}
    {\color{accent}\bfseries Foldables} & Galaxy Z Flip7 & {\color{textsilver} Current} &
    {\color{accent}\bfseries Monitors} & Odyssey OLED G9 & {\color{textsilver} Current} \\
    \rowcolor{tablebg}
    {\color{accent}\bfseries Tablets} & Galaxy Tab S11 Series & {\color{textsilver} Current} &
    {\color{accent}\bfseries Kitchen} & Bespoke AI Refrigerator & {\color{textsilver} Current} \\
    \rowcolor{tablerow}
    {\color{accent}\bfseries Wearables} & Galaxy Watch Ultra & {\color{textsilver} Current} &
    {\color{accent}\bfseries Laundry} & Bespoke AI Laundry & {\color{textsilver} Current} \\
    \rowcolor{tablebg}
    {\color{accent}\bfseries Audio} & Galaxy Buds4 Pro & {\color{gold}\bfseries NEW} &
    {\color{accent}\bfseries Cleaning} & Jet Stick Vacuums & {\color{textsilver} Current} \\
    \rowcolor{tablerow}
    {\color{accent}\bfseries Audio} & Q-series Soundbar & {\color{textsilver} Current} &
    {\color{accent}\bfseries Climate} & Air Conditioners & {\color{textsilver} Current} \\
  \end{tabular}
}

% ══════════════════════════════════════════════════════════
% FOOTER — Tagline
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=6pt, bottom=8pt,
  halign=center, valign=center,
  borderline north={3pt}{0pt}{secondary},
]{name=footer, column=1, span=3, between=row19 and bottom}{
  {\fontsize{38}{46}\selectfont\color{textsilver} Every device works better together\;\textbar\;}%
  {\fontsize{38}{46}\selectfont\bfseries\color{accent} One Ecosystem, Powered by AI}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{textgray} Samsung Galaxy\;\textbar\;samsung.com/galaxy\;\textbar\;\#GalaxyEcosystem2025}
}

\end{tcbposter}
